INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('1', 'Umum', 'Bagaimana cara login ke sistem?', 'Gunakan NIDN Anda sebagai username dan password default \"dosen123\". Setelah login pertama kali, segera ubah password Anda melalui menu Pengaturan untuk keamanan akun.', '1', '1', '45', '4', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('2', 'Umum', 'Apa yang harus dilakukan jika lupa password?', 'Hubungi administrator sistem melalui email support@unpam.ac.id atau telepon 021-7412566. Tim support akan membantu mereset password Anda.', '2', '1', '63', '2', '1', '2026-02-22 19:23:04', '2026-02-28 18:54:17');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('3', 'Umum', 'Bagaimana cara mengubah foto profil?', 'Buka menu Profil, klik pada foto profil Anda, lalu pilih \"Ubah Foto\". Upload foto baru dengan format JPG/PNG maksimal 2MB.', '3', '1', '34', '4', '1', '2026-02-22 19:23:04', '2026-03-01 10:13:54');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('4', 'Sesi Absensi', 'Bagaimana cara membuat sesi absensi baru?', 'Buka menu Sesi Absen, klik tombol \"Buat Sesi Baru\", pilih mata kuliah, tentukan waktu mulai dan durasi, lalu klik \"Buat Sesi\". QR code akan otomatis dibuat.', '1', '1', '16', '4', '1', '2026-02-22 19:23:04', '2026-02-28 18:54:47');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('5', 'Sesi Absensi', 'Berapa lama durasi maksimal sesi absensi?', 'Durasi maksimal sesi absensi adalah 180 menit (3 jam). Anda dapat menutup sesi lebih awal jika diperlukan.', '2', '1', '42', '2', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('6', 'Sesi Absensi', 'Apakah QR code bisa di-regenerate?', 'Ya, Anda dapat me-regenerate QR code kapan saja selama sesi masih aktif. Klik tombol \"Regenerate QR\" pada detail sesi.', '3', '1', '37', '1', '1', '2026-02-22 19:23:04', '2026-03-01 20:36:57');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('7', 'Verifikasi', 'Bagaimana cara menyetujui izin mahasiswa?', 'Buka menu Verifikasi, lihat daftar pengajuan izin, klik detail untuk melihat bukti, lalu klik \"Setujui\" atau \"Tolak\" dengan memberikan catatan jika diperlukan.', '1', '1', '48', '3', '2', '2026-02-22 19:23:04', '2026-03-01 10:13:51');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('8', 'Verifikasi', 'Apa saja jenis izin yang bisa diajukan mahasiswa?', 'Mahasiswa dapat mengajukan izin sakit (dengan surat dokter) atau izin keperluan lain (dengan surat keterangan). Semua pengajuan harus disertai bukti dokumen.', '2', '1', '25', '2', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('9', 'Penilaian', 'Bagaimana sistem menghitung nilai kehadiran?', 'Nilai kehadiran dihitung berdasarkan persentase kehadiran: Hadir = 100%, Izin = 75%, Sakit = 75%, Alpha = 0%. Total nilai adalah rata-rata dari semua pertemuan.', '1', '1', '32', '5', '2', '2026-02-22 19:23:04', '2026-02-28 18:54:34');
INSERT IGNORE INTO help_faqs (id, category, question, answer, order, is_active, helpful_count, not_helpful_count, view_count, created_at, updated_at) VALUES ('10', 'Penilaian', 'Apakah bisa mengubah status kehadiran mahasiswa?', 'Ya, Anda dapat mengubah status kehadiran melalui menu Grading. Pilih mahasiswa, klik \"Override Status\", lalu pilih status baru dan berikan alasan perubahan.', '2', '1', '28', '5', '2', '2026-02-22 19:23:04', '2026-02-28 18:54:42');
INSERT IGNORE INTO help_troubleshooting (id, title, description, category, steps, order, is_active, view_count, created_at, updated_at) VALUES ('1', 'QR Code Tidak Muncul', 'Solusi jika QR code tidak ditampilkan saat membuat sesi absensi', 'Teknis', '[\"Refresh halaman browser dengan menekan Ctrl+F5 (Windows) atau Cmd+Shift+R (Mac)\",\"Pastikan koneksi internet Anda stabil\",\"Coba bersihkan cache browser: Settings > Privacy > Clear browsing data\",\"Jika masih bermasalah, coba gunakan browser lain (Chrome\\/Firefox)\",\"Hubungi support jika masalah berlanjut\"]', '1', '1', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_troubleshooting (id, title, description, category, steps, order, is_active, view_count, created_at, updated_at) VALUES ('2', 'Mahasiswa Tidak Bisa Scan QR', 'Panduan mengatasi masalah mahasiswa yang tidak bisa melakukan scan QR code', 'Absensi', '[\"Pastikan sesi absensi masih dalam status \\\"Aktif\\\"\",\"Cek apakah mahasiswa sudah terdaftar di mata kuliah tersebut\",\"Verifikasi bahwa mahasiswa menggunakan akun yang benar\",\"Pastikan QR code tidak expired (regenerate jika perlu)\",\"Cek apakah mahasiswa berada dalam radius lokasi yang ditentukan\"]', '2', '1', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_troubleshooting (id, title, description, category, steps, order, is_active, view_count, created_at, updated_at) VALUES ('3', 'Data Kehadiran Tidak Tersimpan', 'Langkah-langkah jika data kehadiran mahasiswa tidak tersimpan', 'Teknis', '[\"Cek koneksi internet Anda\",\"Pastikan sesi belum ditutup saat mahasiswa melakukan absen\",\"Refresh halaman dan cek kembali daftar kehadiran\",\"Cek di menu Rekapan untuk memastikan data tersimpan\",\"Jika data hilang, hubungi administrator untuk recovery data\"]', '3', '1', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_troubleshooting (id, title, description, category, steps, order, is_active, view_count, created_at, updated_at) VALUES ('4', 'Tidak Bisa Export Rekapan', 'Solusi jika gagal mengexport rekapan kehadiran ke PDF', 'Laporan', '[\"Pastikan browser Anda mengizinkan pop-up dari situs ini\",\"Coba disable ad-blocker atau extension yang memblokir download\",\"Gunakan browser Chrome atau Firefox versi terbaru\",\"Cek apakah ada data yang perlu diexport (minimal 1 sesi)\",\"Hubungi support jika masalah berlanjut\"]', '4', '1', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
INSERT IGNORE INTO help_troubleshooting (id, title, description, category, steps, order, is_active, view_count, created_at, updated_at) VALUES ('5', 'Notifikasi Tidak Muncul', 'Cara mengaktifkan notifikasi sistem', 'Pengaturan', '[\"Buka menu Pengaturan > Notifikasi\",\"Pastikan semua toggle notifikasi dalam keadaan aktif\",\"Izinkan notifikasi browser: klik ikon gembok di address bar > Notifications > Allow\",\"Cek pengaturan notifikasi di sistem operasi Anda\",\"Refresh halaman setelah mengubah pengaturan\"]', '5', '1', '0', '2026-02-22 19:23:04', '2026-02-22 19:23:04');
